import numpy as np

def mse(y_true, y_pred):
    return np.mean((y_true - y_pred) ** 2)

def huber_loss(y_true, y_pred, delta=1.0):
    error = y_true - y_pred
    is_small_error = np.abs(error) <= delta
    squared_loss = 0.5 * error ** 2
    linear_loss = delta * (np.abs(error) - 0.5 * delta)
    return np.mean(np.where(is_small_error, squared_loss, linear_loss))

def log_cosh_loss(y_true, y_pred):
    error = y_true - y_pred
    return np.mean(np.log(np.cosh(error)))

y_true = np.array([10, 12, 11, 13, 50])  # the same deliberate outlier from the Huber Loss topic
y_pred = np.array([10.5, 11.5, 11.2, 12.8, 15])

print(f"MSE: {mse(y_true, y_pred):.2f}")
print(f"Huber Loss (delta=1.0): {huber_loss(y_true, y_pred, delta=1.0):.2f}")
print(f"Log-Cosh Loss: {log_cosh_loss(y_true, y_pred):.2f}")

print("\nNotice Log-Cosh Loss, like Huber Loss, stays considerably more moderate than MSE")
print("despite the large outlier, and required no delta parameter to be chosen at all")
